//go:build riscv64

package floats

// RVV 1.0 kernels (gated on hasRVV, kernels_riscv64.go): the float64 Add, Sub,
// Mul, Div, Sqrt of go-ndarray and the pairwise-sum block, generated by go-asmgen
// (lanes_riscv64_gen.go) into lanes_riscv64.s. One IEEE operation per element, no
// fused instruction: bit-identical to the scalar loops. The callers pass every
// slice already sliced to the common length.
//
//go:noescape
func addRVV(dst, a, b *float64, n int)

//go:noescape
func subRVV(dst, a, b *float64, n int)

//go:noescape
func mulRVV(dst, a, b *float64, n int)

//go:noescape
func divRVV(dst, a, b *float64, n int)

//go:noescape
func sqrtRVV(dst, src *float64, n int)

// pwBlockRVV is the 8 <= n <= 128 block of DOUBLE_pairwise_sum.
//
//go:noescape
func pwBlockRVV(a *float64, n int) float64

func add(dst, a, b []float64) {
	if len(a) == 0 || !hasRVV {
		addRef(dst, a, b)
		return
	}
	addRVV(&dst[0], &a[0], &b[0], len(a))
}

func sub(dst, a, b []float64) {
	if len(a) == 0 || !hasRVV {
		subRef(dst, a, b)
		return
	}
	subRVV(&dst[0], &a[0], &b[0], len(a))
}

func mul(dst, a, b []float64) {
	if len(a) == 0 || !hasRVV {
		mulRef(dst, a, b)
		return
	}
	mulRVV(&dst[0], &a[0], &b[0], len(a))
}

func div(dst, a, b []float64) {
	if len(a) == 0 || !hasRVV {
		divRef(dst, a, b)
		return
	}
	divRVV(&dst[0], &a[0], &b[0], len(a))
}

func sqrt(dst, src []float64) {
	if len(src) == 0 || !hasRVV {
		sqrtRef(dst, src)
		return
	}
	sqrtRVV(&dst[0], &src[0], len(src))
}

func clampScalar(dst, v []float64, lo, hi float64) { clampScalarRef(dst, v, lo, hi) }

func pairwiseBlock(a []float64) float64 {
	if !hasRVV {
		return pairwiseBlockRef(a)
	}
	return pwBlockRVV(&a[0], len(a))
}
